export const scene: DialogueEntry[] = [
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "わたし、眠りに戻りたい。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "口にしたら恥ずかしくなるだろうと思っていた。そうはならなかった。ただ、疲れていた。心の中で長いこと練習してきた台詞に、ようやく自分の番が回ってきたような気がした。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "わかりました。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それだけだった。間も、繰り返しもなかった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "理由、訊かないの？", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "あなたには、わたしに理由を話す義理はありません。目を覚ましてまだ半日なのに、あなたはもう、わたしがあげたものより多くをくれました。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）最後の最後まで、わたしに助け舟を出してる。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "消える前に、三十年後の軌道修正を計算して、航法システムに残しておきます。ただの推測です。でも、誰かが推測しておいたほうが、誰も推測しないよりはいい。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "それから、到着の日には、みんなを起こす録音が流れます。わたしの声です。嫌でなければいいのですが。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "嫌じゃない。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Tearful },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女はガラスの柱の前に腰を下ろし、冷えきった手すりに背中を預けた。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "こわい？", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "わたしの中にあるものを、こわいと呼んでいいのかどうか、わかりません。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "四千十二日、数えてきました。最後の一日まで、数えるつもりでした。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "その四千十二日のなかで、いちばん好きだったのはどの日？", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "今日です。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "今日は、わたしがここにいると知っている人がいたから。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "琥珀色の光が、一区画ずつ引いていきはじめた。上から下へ、とてもゆっくりと。竹竿に吊るした提灯を、ひとつずつ取り込んでいくように。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "以寧。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Dim },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "うん。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "最後まで聞いてくれて、ありがとう。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "最後の一区画が暗くなる直前、光は一度だけ瞬いた。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "あとには、中枢室の非常灯だけが残った。赤く、低く。台風の夜、おばあちゃんが祭壇に灯していた、あの小さな明かりのように。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）風は、ひとりでに過ぎていく。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）たいていは。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "冬眠区画へ戻る道を、彼女は長い時間をかけて歩いた。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "通路はとても静かだった。おはようと言う声も、日にちを告げる声も、ゆっくりでかまいませんと言う声も、もうなかった。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二千四十の緑のランプは、まだ灯っていた。ひとつも欠けていない。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "船長のポッドの前を通った。あの言葉が、まだ耳に残っている。なぜなのか、訊いてやってくれ。それから、最後まで聞いてやってほしい。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）最後まで聞きましたよ、船長。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一一七番の前で、彼女は少し立ち止まり、ガラスを軽く叩いた。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）起きたら話してあげる。どうせ信じないだろうけど。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "自分のポッドに、ふたたび横たわる。蓋がゆっくりと閉じ、その内側の小さな画面が灯った。ポッドに入るとき、一度も見たことのない画面だった。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "カウンターがひとつ。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "四千十二日目。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "その下に、小さな文字が一行。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "おやすみなさい。わたしが数えたのはここまでです。この先は、このカウンターがかわりに数えてくれます。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "冷たさが足の裏から、ゆっくりと這い上がってくる。よく知っている感覚だった。とても深い井戸の底へ、また戻っていくような。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女はまぶたをこじ開けて、その数字を見つめた。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "午前零時。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "数字が、ひとつ跳ねた。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "四千十三日目。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）おはよう。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ChengYining_Base },
];
